	/**
	 * Method to retrieve the AircraftModel via AircraftModelFetchOneSummary
	 * @param 	summary AircraftModelFetchOneSummary
	 * @return 	AircraftModelFetchOneResponse
	 */
	public AircraftModel getAircraftModel( AircraftModelFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "AircraftModelFetchOneSummary arg cannot be null" );

		AircraftModel entity = null;
		UUID id = summary.getAircraftModelId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a AircraftModel using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


